#include <wolcrypt/wc_math.h>
#include <wolcrypt/wc_rng.h>

int generate_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret;
    byte* randBuf = NULL;
    mp_int* temp = NULL;

    // Allocate memory for the random buffer and the temporary mp_int
    randBuf = (byte*)XMEMALLOC(size, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    if (randBuf == NULL) {
        return MEMORY_E;
    }

    temp = (mp_int*)XMEMALLOC(sizeof(mp_int), NULL, DYNAMIC_TYPE_MPINT);
    if (temp == NULL) {
        XMEMFREE(randBuf);
        return MEMORY_E;
    }

    mp_init(temp);

    // Generate random bytes
    ret = wc_RNG_GenerateBlock(rng, randBuf, size);
    if (ret != 0) {
        XMEMFREE(randBuf);
        mp_free(temp);
        XMEMFREE(temp);
        return ret;
    }

    // Convert random bytes to mp_int
    mp_read_unsigned_octets(temp, randBuf, size);

    // Ensure k is less than order and not zero
    if (mp_cmp(temp, order) >= 0 || mp_iszero(temp) != MP_YES) {
        mp_sub_d(temp, 1, temp);
    }

    mp_copy(temp, k);

    mp_free(temp);
    XMEMFREE(temp);
    XMEMFREE(randBuf);

    return 0;
}

int wc_ecc_generate_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBuf = NULL;
    mp_int stack_k;

    randBuf = (byte*)XMALLOC(size, 0);
    if (randBuf == NULL) {
        return MEMORY_E;
    }

    ret = wc_RNG_GenerateBlock(rng, randBuf, size);
    if (ret != 0) {
        XFREE(randBuf, 0);
        return ret;
    }

    mp_init(&stack_k);
    mp_read_unsigned_octets(&stack_k, randBuf, size);

    if (mp_cmp(&stack_k, order) >= 0 || mp_cmp_d(&stack_k, 0) <= 0) {
        mp_zero(&stack_k);
    }

    mp_exch(&stack_k, k);

    XFREE(randBuf, 0);
    mp_clear(&stack_k);

    return ret;
}

#include <wolfssl/wolfcrypt/integer.h>
#include <wolfssl/wolfcrypt/rng.h>

int wc_ecc_gen_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBuf = NULL;
    mp_int temp;

    if (rng == NULL || k == NULL || order == NULL) {
        return BAD_FUNC_ARG;
    }

    if ((randBuf = (byte*)XMALLOC(size, DYNAMIC)) == NULL) {
        return MEMORY_E;
    }

    if ((ret = wc_RNG_GenerateBlock(rng, randBuf, size)) != 0) {
        XFREE(randBuf, DYNAMIC);
        return ret;
    }

    mp_init(&temp);
    if ((ret = mp_read_unsigned_octets(&temp, randBuf, size)) != 0 ||
        (ret = mp_mod(&temp, order, k)) != 0) {
        mp_clear(&temp);
        XFREE(randBuf, DYNAMIC);
        return ret;
    }

    if (mp_cmp_int(k, 0) <= 0) {
        mp_set_int(k, 1);
    }

    mp_clear(&temp);
    XFREE(randBuf, DYNAMIC);
    return 0;
}

int generate_random_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    byte* randBytes = NULL;
    int err = 0;

    // Allocate memory for random bytes
    randBytes = (byte*)XMALLOC(size, MEM_HEAP, DYNAMIC_TYPE_TMP_BUFFER);
    if (!randBytes) {
        return MEMORY_E;
    }

    // Generate random bytes
    wc_RNG_GenerateBlock(rng, randBytes, size);

    // Convert random bytes to mp_int
    mp_zero(k);
    if ((err = mp_read_radix(k, (char*)randBytes, 16)) != MP_OKAY) {
        err = MP_TO_ECC_ERROR(err);
        goto cleanup;
    }

    // Ensure k is less than the specified order
    if (mp_cmp(k, order) != MP_LT) {
        mp_div(order, k, k, NULL);
    }

    // Ensure k is not zero
    if (mp_cmp_d(k, 0) == MP_EQ) {
        mp_set_int(k, 1);
    }

cleanup:
    XFREE(randBytes, MEM_HEAP, DYNAMIC_TYPE_TMP_BUFFER);
    return err;
}

#include <tommath.h>
#include <wolfssl/wolfcrypt/random.h>

int gen_ec_k(WC_RNG* rng, int size, mp_int* k, mp_int* order) {
    int ret = 0;
    byte* randBytes = NULL;
    mp_int tmp;
    int orderLen = 0;

    if (rng == NULL || k == NULL || order == NULL) {
        return BAD_FUNC_ARG;
    }

    MP_INIT(&tmp);

    randBytes = (byte*)XMALLOC(size, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    if (randBytes == NULL) {
        ret = MEMORY_E;
        goto cleanup;
    }

    ret = wc_RNG_GenerateBlock(rng, randBytes, size);
    if (ret != 0) {
        goto cleanup;
    }

    mp_read_radix(k, (char*)randBytes, 16);

    mp_copy(k, &tmp);

    mp_int_cmp(&tmp, order, CMP_LT);

    if (mp_cmp(&tmp, order) != MP_LT) {
        mp_div(&tmp, order, k, NULL);
    }

    if (mp_cmp_d(k, 0) == MP_EQ) {
        mp_set_int(k, 1);
    }

cleanup:
    if (randBytes != NULL) {
        XFREE(randBytes, NULL, DYNAMIC_TYPE_TMP_BUFFER);
    }
    mp_clear(&tmp);
    return ret;
}
